<?php use SwimlogStandalone\EfficiencyTrends as ET;use SwimLogEvaluation\Workout; ?>
<section class="calendar-panel workout-page" aria-labelledby="efficiency-title"><h2 id="efficiency-title">Efficiency Trends</h2>
<p>Monthly recorded pool-swim pace, SWOLF and strokes per length. Strokes, pool lengths and meter/yard courses remain separate. A lower SWOLF alone does not establish better technique: compare it with pace and sample coverage. Months with missing evidence stay missing; the current month may be partial.</p>
<?php if(is_wp_error($efficiency)): ?><p role="alert"><?php echo esc_html($efficiency->get_error_message()); ?></p><?php else:$r=$efficiency; ?>
<form method="get" class="log-filters"><input type="hidden" name="screen" value="efficiency"><div><label for="eff-months">Period (months)</label><input id="eff-months" name="months" type="number" min="1" max="24" required value="<?php echo esc_attr($r['months']); ?>"></div><div><label for="eff-course">Course</label><select id="eff-course" name="course"><?php foreach(array('m'=>'Meters','yd'=>'Yards')as$key=>$label): ?><option value="<?php echo esc_attr($key); ?>" <?php selected($r['course'],$key); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></div><div><label for="eff-stroke">Stroke</label><select id="eff-stroke" name="stroke"><option value="">All strokes</option><?php foreach($r['strokes']as$key=>$label): ?><option value="<?php echo esc_attr($key); ?>" <?php selected($r['stroke'],$key); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></div><button>Apply filters</button></form>
<?php if(!$r['data']['groups']): ?><p>No qualifying active-length evidence is available.</p><?php endif;foreach($r['data']['groups']as$g): ?><section class="comparison-stroke"><h3><?php echo esc_html(($r['strokes'][$g['stroke']]??$g['stroke']).' · '.$g['pool_length'].' '.$g['course_unit'].' pool'); ?></h3><p>Rest and zero-distance lengths are excluded by the plugin. Timing and stroke-count coverage can differ; these metrics may describe different subsets of the recorded lengths.</p>
<div class="comparison-graphics"><?php foreach(array('avg_pace_100_ms'=>'Pace per 100 '.$g['course_unit'],'avg_swolf'=>'SWOLF','avg_stroke_count'=>'Strokes per length')as$key=>$label): ?><section><h4><?php echo esc_html($label); ?></h4><?php echo ET::chart($g['months'],$key,$label.' monthly trend; exact values and samples in table'); ?></section><?php endforeach; ?></div>
<div class="entry-compare"><table><caption>Monthly metrics and evidence coverage; gaps are not interpolated</caption><thead><tr><th scope="col">Month</th><th scope="col">Swims / active lengths</th><th scope="col">Pace per 100</th><th scope="col">Timed lengths</th><th scope="col">SWOLF</th><th scope="col">SWOLF samples</th><th scope="col">Strokes/length</th><th scope="col">Stroke-count samples</th></tr></thead><tbody><?php foreach($g['months']as$m): ?><tr><th scope="row"><?php echo esc_html($m['month']); ?></th><td><?php echo esc_html($m['workout_count'].' / '.$m['active_lengths']); ?></td><td><?php echo esc_html(Workout::format_duration($m['avg_pace_100_ms'])); ?></td><td><?php echo esc_html($m['timed_lengths']); ?></td><td><?php echo esc_html($m['avg_swolf']===null?'—':number_format_i18n($m['avg_swolf'],2)); ?></td><td><?php echo esc_html($m['swolf_lengths']); ?></td><td><?php echo esc_html($m['avg_stroke_count']===null?'—':number_format_i18n($m['avg_stroke_count'],2)); ?></td><td><?php echo esc_html($m['stroke_count_lengths']); ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endforeach;endif; ?></section>
